"""Build a local, model-blinded owner review document from public posting text."""
import argparse, json
from pathlib import Path
from representative_contract import questions

def main():
 p=argparse.ArgumentParser();p.add_argument('--root',type=Path,required=True);a=p.parse_args();r=a.root
 jobs=json.loads((r/'dataset.json').read_text());labels=json.loads((r/'real-labels.json').read_text());expected={j['id']:j['expected'] for j in labels}
 # Deliberately omit provider answers, internal report notes and reporter details.
 rows=[{'id':j['id'],'title':j['title'],'company':j.get('company_name',j.get('company','')),'location':j.get('location'),'url':j.get('url'),'text':j['description_text'],'stratum':j['sampling_stratum'],'kind':j['kind'],'expected':j.get('expected',expected.get(j['id'],{}))} for j in jobs]
 payload=json.dumps({'rows':rows,'questions':questions()},ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
 page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Pinkslip benchmark review</title><style>body{font:16px system-ui;max-width:1000px;margin:24px auto;padding:0 16px}button,select{font:inherit;padding:8px;margin:4px}pre{white-space:pre-wrap;font:inherit;line-height:1.5}label{display:block;border-bottom:1px solid #ddd;padding:8px}details{margin:12px 0}.notice{background:#eee;padding:12px}</style><h1>Pinkslip benchmark review</h1><p class="notice">These annotations are provisional. Model answers are hidden. Review the complete posting and edit only fields you can establish; leave uncertain or unreviewed fields blank. Nothing is sent to Pinkslip or a model.</p><select id="filter"><option value="all">All cases</option><option value="real">Real postings</option><option value="synthetic">Controlled cases</option></select><button id="previous">Previous</button><button id="next">Next</button><button id="export">Export annotations</button><p id="position"></p><h2 id="title"></h2><p id="meta"></p><a id="source" target="_blank" rel="noopener noreferrer">Original posting</a><details><summary>Complete posting text</summary><pre id="text"></pre></details><div id="fields"></div><script type="application/json" id="data">PAYLOAD</script><script>
const data=JSON.parse(document.getElementById('data').textContent);const el=id=>document.getElementById(id);let position=0;const edits=new Map();
function selected(){return data.rows.filter(r=>el('filter').value==='all'||r.kind===el('filter').value)}
function render(){const rows=selected();position=Math.max(0,Math.min(position,rows.length-1));const row=rows[position];el('position').textContent=`${position+1} / ${rows.length} — ${row.stratum}`;el('title').textContent=row.title;el('meta').textContent=[row.company,row.location].filter(Boolean).join(' · ');el('source').hidden=!row.url;el('source').href=/^https?:\\/\\//.test(row.url||'')?row.url:'#';el('text').textContent=row.text;el('fields').replaceChildren();const values=edits.get(row.id)||{...row.expected};
for(const [key,q] of Object.entries(data.questions)){const label=document.createElement('label');const name=document.createElement('strong');name.textContent=key+' ';label.append(name);const select=document.createElement('select');const blank=document.createElement('option');blank.value='';blank.textContent='Unreviewed / unset';select.append(blank);for(const [value,description] of Object.entries(q.criteria)){const option=document.createElement('option');option.value=value;option.textContent=value+' — '+description;select.append(option)}select.value=values[key]||'';select.onchange=()=>{if(select.value)values[key]=select.value;else delete values[key];edits.set(row.id,values)};label.append(select);const details=document.createElement('details');const summary=document.createElement('summary');summary.textContent='Question instructions';const text=document.createElement('p');text.textContent=q.instructions;details.append(summary,text);label.append(details);el('fields').append(label)}}
el('filter').onchange=()=>{position=0;render()};el('previous').onclick=()=>{position--;render()};el('next').onclick=()=>{position++;render()};el('export').onclick=()=>{const rows=[...edits].map(([id,values])=>{const original=data.rows.find(r=>r.id===id).expected;const expected=Object.fromEntries(Object.entries(values).filter(([k,v])=>original[k]!==v));const unset_fields=Object.keys(original).filter(k=>!(k in values));return {id,expected,unset_fields,annotation_source:'owner_edited_fields_only'}});const blob=new Blob([JSON.stringify({note:'Edited fields only; unchanged cases are not claimed reviewed.',annotations:rows},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='pinkslip-owner-annotations.json';a.click();URL.revokeObjectURL(url)};render();
</script></html>'''.replace('PAYLOAD',payload)
 (r/'review.html').write_text(page);print(json.dumps({'review_cases':len(rows),'provider_answers_included':False,'output':str(r/'review.html')}))
if __name__=='__main__':main()
